import './app.js';
import {esc} from './clues.js';
import {celebrate} from './celebration.js';
const $=selector=>document.querySelector(selector),roleName=role=>({civilian:'平民',spy:'卧底',blank:'白板'}[role]);
let room,busy=false,socket,reconnectTimer,reconnects=0,offset=0,visibleWord=false,lastMatch,lastSync;
function notice(text='',target='#uc-notice',error=false){const el=$(target);el.textContent=text;el.hidden=!text;el.classList.toggle('error',error);el.setAttribute('role',error?'alert':'status');}
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)}),signal:AbortSignal.timeout(15000)});const value=await response.json();if(!response.ok)throw Object.assign(Error(value.error||'暂时无法读取，请重试'),{status:response.status});return value;}
const path=action=>'/api/rooms/'+room.code+'/'+action;
const payload=()=>({matchId:room.undercover.matchId,ballot:room.undercover.ballot});
const name=id=>room?.players.find(p=>p.id===id)?.nickname||'玩家';
function settingFields(prefix){return `<label class="filter-field">人数上限<select id="${prefix}-capacity">${Array.from({length:8},(_,i)=>`<option value="${i+3}" ${i===3?'selected':''}>${i+3}人</option>`).join('')}</select></label><label class="filter-field">卧底数量<select id="${prefix}-spies"><option value="0">自动（按实际人数）</option><option value="1">1名卧底</option><option value="2">2名卧底</option><option value="3">3名卧底</option></select></label><div class="uc-setting-toggles"><label class="uc-setting-check"><input type="checkbox" id="${prefix}-blank"><span><strong>开启白板</strong><small>加入1名无词玩家 · 默认关闭</small></span></label><label class="uc-setting-check"><input type="checkbox" id="${prefix}-anonymous-voting"><span><strong>匿名投票</strong><small>只公开票数，隐藏投票明细 · 默认关闭</small></span></label></div>`;}
$('#uc-create-settings').innerHTML=settingFields('uc-create');$('#uc-host-settings').innerHTML=settingFields('uc-host');
function settings(prefix){return {mode:'undercover',capacity:Number($('#'+prefix+'-capacity').value),spies:Number($('#'+prefix+'-spies').value),blank:$('#'+prefix+'-blank').checked,anonymousVoting:$('#'+prefix+'-anonymous-voting').checked};}
function counts(count,s){const spy=s.spies||(count<=5?1:count<=8?2:3),blank=s.blank?1:0;return {spy,blank,civilian:count-spy-blank,valid:count>=3&&count-spy-blank>=1&&spy<count-spy};}
function settingNote(prefix){const s=settings(prefix),n=prefix==='uc-host'?room?.players.length||s.capacity:s.capacity,c=counts(n,s);$('#'+prefix+'-counts').textContent=n<3?'当前'+n+'人，请等待至少3人入房后开局。'+(s.blank?'白板已开启，将替换1名平民。':'白板关闭。'):(prefix==='uc-host'?'当前'+n+'人':'满员'+n+'人')+'：'+Math.max(0,c.civilian)+'名平民 · '+c.spy+'名卧底'+(c.blank?' · 1名白板':' · 白板关闭')+'。'+(!c.valid?'身份数量不适合当前人数，请减少卧底。':s.blank&&n===3?'3人开启白板：白板存活到最后两人即获胜。':'自动分配按实际开局人数计算。');}
for(const prefix of ['uc-create','uc-host'])for(const suffix of ['capacity','spies','blank','anonymous-voting'])$('#'+prefix+'-'+suffix).addEventListener('change',()=>settingNote(prefix));settingNote('uc-create');
function exit(text){const old=socket;socket=null;clearTimeout(reconnectTimer);old?.close();room=null;visibleWord=false;$('#uc-room').hidden=true;$('#uc-entry').hidden=false;try{localStorage.removeItem('chu-yiba:undercover-room');}catch{}if(text)notice(text,'#uc-notice',true);}
function accept(value){
 if(value.settings.mode!=='undercover'){location.replace('/multi?room='+encodeURIComponent(value.code));return;}
 if(room&&room.code===value.code&&value.version<room.version)return;
 const changed=room?.code!==value.code||lastMatch!==value.undercover?.matchId,wasFinished=room?.stage==='finished';
 if(changed){visibleWord=false;$('#uc-blank-word').value='';$('#uc-blank-error').hidden=true;}
 room=value;lastMatch=room.undercover?.matchId;offset=(value.timer.serverNow||Date.now())-Date.now();try{localStorage.setItem('chu-yiba:undercover-room',room.code);}catch{}
 $('#uc-entry').hidden=true;$('#uc-room').hidden=false;render();
 if(!changed&&!wasFinished&&room.stage==='finished'&&room.undercover?.result?.winners.includes(room.me))celebrate('undercover|'+room.code+'|'+lastMatch,'你所在的阵营获胜了！');
}
async function sync(){if(!room)return;try{accept(await api(path('state')));}catch(error){if(error.status===404)exit(error.message);throw error;}}
async function run(task,target='#uc-notice'){
 if(busy)return;busy=true;notice('',target);render();$('#uc-create').disabled=true;$('#uc-join').disabled=true;
 try{await task();}catch(error){notice((target.includes('create')?'创建失败：':target.includes('join')?'加入失败：':'')+(error.name==='TimeoutError'?'网络超时，请重试。':error.message),target,true);if(room&&[404,409].includes(error.status))try{await sync();}catch{}}
 finally{busy=false;$('#uc-create').disabled=false;$('#uc-join').disabled=false;render();}
}
async function action(type,data={}){accept(await api(path(type),data));}
function connect(){
 if(!room)return;clearTimeout(reconnectTimer);socket?.close();const code=room.code,current=socket=new WebSocket(location.origin.replace(/^http/,'ws')+'/api/rooms/'+code+'/events');
 current.onopen=()=>{if(current!==socket)return;reconnects=0;$('#uc-connection').textContent='实时同步已连接';};
 current.onmessage=e=>{if(current!==socket)return;try{const data=JSON.parse(e.data);if(data.type==='state')accept(data.state);else if(data.type==='closed')exit(data.reason);}catch{notice('房间更新暂时无法读取，请重新连接。','#uc-notice',true);}};
 current.onclose=()=>{if(current!==socket||room?.code!==code)return;$('#uc-connection').textContent='连接中断，正在重连…';if(reconnects<6)reconnectTimer=setTimeout(async()=>{reconnects++;try{await sync();}catch{}if(room?.code===code)connect();},Math.min(30000,1000*2**reconnects));};
}
function render(){
 if(!room)return;const u=room.undercover,host=room.host===room.me,lobby=room.stage==='lobby',playing=room.stage==='playing',ended=['finished','cancelled'].includes(room.stage),me=room.players.find(p=>p.id===room.me);
 $('#uc-code').textContent=room.code;$('#uc-member-count').textContent=room.players.length+' / '+room.settings.capacity;$('#uc-member-note').textContent=lobby?'全部准备后开始':ended?'本房间累计胜局':'存活 '+room.players.filter(p=>p.alive).length+' 人';
 $('#uc-room-settings-label').textContent='3—10人 · 上限'+room.settings.capacity+'人 · '+(room.settings.spies?room.settings.spies+'名卧底':'卧底自动分配')+' · '+(room.settings.blank?'白板开启':'白板关闭')+' · '+(room.settings.anonymousVoting?'匿名投票':'公开投票')+' · 66题';
 $('#uc-players').innerHTML=room.players.map(p=>`<li class="${p.id===room.me?'is-me ':''}${!p.alive?'eliminated':''}"><strong>${esc(p.nickname)}</strong><span class="uc-player-meta">${p.id===room.me?'<span class="uc-player-badge">你</span>':''}${p.id===room.host?'<span class="uc-player-badge">房主</span>':''}<span>${p.connected?'在线':'暂时断线'}</span>${ended?'<span>'+p.score+'场胜利</span>':''}</span><span class="uc-player-state ${lobby&&p.ready?'ready':''}">${lobby?(p.ready?'✓ 已准备':'等待准备'):!p.alive?'已淘汰 · '+roleName(p.role):ended?roleName(p.role):u.phase==='voting'?(u.voted.includes(p.id)?'✓ 已投票':'等待投票'):'存活'}</span>${ended?`<span class="uc-player-word">${p.word===null?'白板无词':esc(p.word)}</span>`:''}</li>`).join('');
 $('#uc-ready').hidden=!lobby;$('#uc-ready').textContent=me.ready?'✓ 已准备 · 取消':'点击准备';$('#uc-ready').classList.toggle('ready-complete',me.ready);$('#uc-start').hidden=!(host&&lobby);const c=counts(room.players.length,room.settings);$('#uc-start').disabled=busy||!c.valid||room.players.some(p=>!p.ready);
 $('#uc-rematch').hidden=!(host&&ended);$('#uc-start-vote').hidden=!(host&&playing&&['discussion','runoff-discussion'].includes(u.phase));$('#uc-start-vote').textContent=u?.phase==='runoff-discussion'?'补充描述完成，开始复投':'描述完成，开始投票';
 $('#uc-leave').hidden=playing;$('#uc-close').hidden=!(host&&playing);$('#uc-host-form').hidden=!(host&&lobby);
 if(lobby){for(const key of ['capacity','spies'])$('#uc-host-'+key).value=String(room.settings[key]);$('#uc-host-blank').checked=Boolean(room.settings.blank);$('#uc-host-anonymous-voting').checked=Boolean(room.settings.anonymousVoting);settingNote('uc-host');}
 const ready=room.players.filter(p=>!p.ready).length;$('#uc-progress').textContent=lobby?(!me.ready?'你还没有准备，请点击「准备」。':'你已准备。')+(room.players.length<3?' 等待至少3位玩家。':!c.valid?' 身份组合不适合当前人数，请房主调整。':ready?' 还有'+ready+'人未准备。':host?' 全员准备，可以开始发词！':' 等待房主发词。'):playing?!me.alive&&u.blankPlayer!==room.me?'你已淘汰，接下来只可观战；请勿透露自己的词语。':u.phase==='voting'?'投票结束前可以改票；全部存活玩家提交后提前结算。':u.phase==='blank-guess'?'白板猜词进行中，结果确定后再判定胜负。':'按建议顺序在语音通话或线下描述，不要直接说出歌名。':room.stage==='cancelled'?'房主已结束本局；身份与词语已公开。':'本局结束，等待房主返回准备页。';
 $('#uc-personal-card').hidden=!playing;$('#uc-secret').hidden=!visibleWord;$('#uc-word-hidden').hidden=visibleWord;$('#uc-toggle-word').textContent=visibleWord?'收起词语':'查看我的词语';$('#uc-toggle-word').setAttribute('aria-expanded',String(visibleWord));
 if(u){$('#uc-word').textContent=u.personal.isBlank?'你是白板 · 没有词语':u.personal.word;$('#uc-word-note').textContent=u.personal.isBlank?'听取其他人的描述，推断平民歌曲名。':'你的阵营暂不公开，根据其他人的描述判断自己的处境。';}
 $('#uc-order').hidden=!(playing&&['discussion','runoff-discussion'].includes(u.phase));if(u)$('#uc-order').innerHTML='<strong>建议发言顺序 · 第'+u.round+'轮</strong>'+u.speakingOrder.map(id=>esc(name(id))+(id===room.me?'（你）':'')).join(' → ');
 $('#uc-vote-panel').hidden=!(playing&&u.phase==='voting');
 if(playing&&u.phase==='voting'){const alive=room.players.filter(p=>p.alive),canVote=me.alive&&!busy&&room.timer.deadlineAt>Date.now()+offset;$('#uc-vote-progress').textContent=u.voted.length+' / '+alive.length+'人已提交';$('#uc-vote-note').textContent=!me.alive?'你已淘汰，可以观看投票进度。':u.runoff?'本次仅对最高票平票玩家复投；仍不能投自己。':u.myVote?'你已投给'+(u.myVote.target===null?'弃权':name(u.myVote.target))+'，结束前可点击改票。':'点击一位玩家提交投票，也可以弃权。';
  const options=[...room.players.filter(p=>u.candidates.includes(p.id)),{id:null,nickname:'本轮弃权'}];$('#uc-vote-options').innerHTML=options.map(p=>`<button type="button" data-vote="${p.id===null?'abstain':esc(p.id)}" class="${u.myVote?.target===p.id?'selected':''}" ${!canVote||p.id===room.me?'disabled':''}>${esc(p.nickname)}<small>${p.id===room.me?'不能投自己':u.myVote?.target===p.id?'✓ 已选择':p.id===null?'不计入候选票数':'点击投给这位玩家'}</small></button>`).join('');
 }
 $('#uc-blank-panel').hidden=!(playing&&u.phase==='blank-guess'&&u.blankPlayer===room.me);$('#uc-blank-submit').disabled=busy;$('#uc-blank-word').disabled=busy;
 $('#uc-ballot').hidden=!u?.lastBallot;if(u?.lastBallot){const b=u.lastBallot;$('#uc-ballot-summary').textContent=b.eliminated?name(b.eliminated)+' 被淘汰 · '+roleName(room.players.find(p=>p.id===b.eliminated).role):b.tied?(u.phase==='runoff-discussion'?'最高票平票，请平票玩家补充描述后复投。':'复投仍平票，本轮无人淘汰。'):'本轮全部弃权，无人淘汰。';if(u.blankGuess?.playerId===b.eliminated)$('#uc-ballot-summary').textContent+=u.blankGuess.correct?'，白板猜中了平民词。':u.blankGuess.timedOut?'，白板猜词超时。':'，白板未猜中平民词。';$('#uc-tallies').innerHTML=Object.entries(b.counts).sort((a,b)=>b[1]-a[1]).map(([id,n])=>'<div class="uc-tally"><span>'+esc(name(id))+'</span><strong>'+n+'票</strong></div>').join('');$('#uc-vote-breakdown').hidden=Boolean(b.anonymous);$('#uc-ballot-privacy').hidden=!b.anonymous;$('#uc-vote-details').innerHTML=(b.votes||[]).map(v=>'<li>'+esc(name(v.playerId))+' → '+(v.target===null?'弃权 / 未提交':esc(name(v.target)))+'</li>').join('');}
 $('#uc-result').hidden=!ended;if(ended&&u){const result=u.result,title=room.stage==='cancelled'?'本局已结束':roleName(result.winner)+'获胜！',reason=room.stage==='cancelled'?'对局取消，不计胜局。':{guessed:'白板一次猜中了平民词。',survived:'白板存活到最后两人。',eliminated:'全部卧底和白板已被淘汰。',parity:'卧底人数不少于其余存活玩家。'}[result.reason];$('#uc-result').innerHTML='<h3>'+title+'</h3><p>'+reason+'</p><div class="uc-result-words"><div><span>平民词</span><strong>'+esc(u.words.civilian)+'</strong></div><div><span>卧底词</span><strong>'+esc(u.words.spy)+'</strong></div></div>';}
 $('#uc-room').querySelectorAll('button').forEach(b=>{if(!['uc-start','uc-toggle-word'].includes(b.id)&&!b.hasAttribute('data-vote'))b.disabled=busy;});renderClock();
}
function renderClock(){
 if(!room)return;const u=room.undercover,playing=room.stage==='playing',phase=playing?u.phase:'lobby',timed=['voting','blank-guess','lobby'].includes(phase),left=Math.max(0,Math.ceil((room.timer.deadlineAt-Date.now()-offset)/1000));
 $('#uc-stage-label').textContent=playing?'第'+u.round+'轮 · '+(u.runoff?'复投':'谁是卧底'):room.stage==='lobby'?'等待开局':'答案已揭晓';$('#uc-stage-title').textContent={discussion:'轮流描述，寻找不同', 'runoff-discussion':'平票了，请补充描述',voting:u?.runoff?'正在复投':'开始投票', 'blank-guess':'等待 '+name(u?.blankPlayer)+' 猜词',lobby:room.stage==='lobby'?'朋友到齐后，一起开始':'本局结束'}[phase]||'本局结束';
 $('#uc-stage-note').textContent=phase==='voting'?'全员提交或60秒到时自动结算':phase==='blank-guess'?'白板有一次猜词机会，其他玩家请等待。':phase==='lobby'?(room.stage==='lobby'?'房间等待10分钟未开始会自动关闭。':'房间将在倒计时结束后关闭，可以再来一局。'):phase==='runoff-discussion'?'最高票玩家补充描述后，由房主开始复投。':'在外部语音通话或线下交流，房主在描述完成后开启投票。';
 $('#uc-clock').hidden=!timed;$('#uc-clock').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');$('#uc-stage-banner').classList.toggle('urgent',timed&&left<=15);
 if(timed&&left===0&&!busy&&lastSync!==room.timer.deadlineAt){lastSync=room.timer.deadlineAt;void sync().catch(e=>notice(e.message,'#uc-notice',true));}
}
$('#uc-create').addEventListener('click',()=>void run(async()=>{const value=await api('/api/rooms',{nickname:$('#uc-nickname').value,...settings('uc-create')});accept(value);try{localStorage.setItem('chu-yiba:nickname',$('#uc-nickname').value);}catch{}connect();},'#uc-create-error'));
$('#uc-join-form').addEventListener('submit',e=>{e.preventDefault();void run(async()=>{const code=$('#uc-join-code').value.trim().toUpperCase();if(!/^[A-HJ-NP-Z2-9]{6}$/.test(code))throw Error('请填写正确的6位房间码');accept(await api('/api/rooms/'+code+'/join',{nickname:$('#uc-nickname').value}));connect();},'#uc-join-error');});
$('#uc-ready').addEventListener('click',()=>void run(()=>action('ready',{ready:!room.players.find(p=>p.id===room.me).ready})));$('#uc-start').addEventListener('click',()=>void run(()=>action('start')));$('#uc-start-vote').addEventListener('click',()=>void run(()=>action('start-vote',payload())));$('#uc-rematch').addEventListener('click',()=>void run(()=>action('rematch')));
$('#uc-host-form').addEventListener('submit',e=>{e.preventDefault();const draft=settings('uc-host');void run(()=>action('configure',draft));});$('#uc-toggle-word').addEventListener('click',()=>{visibleWord=!visibleWord;render();});
$('#uc-vote-options').addEventListener('click',e=>{const b=e.target.closest('[data-vote]');if(!b||b.disabled)return;void run(()=>action('vote',{...payload(),target:b.dataset.vote==='abstain'?null:b.dataset.vote}),'#uc-vote-error');});
$('#uc-blank-form').addEventListener('submit',e=>{e.preventDefault();void run(()=>action('blank-guess',{...payload(),word:$('#uc-blank-word').value}),'#uc-blank-error');});
$('#uc-reconnect').addEventListener('click',()=>void run(async()=>{await sync();connect();}));$('#uc-leave').addEventListener('click',()=>void run(async()=>{await api(path('leave'),{});exit();}));$('#uc-close').addEventListener('click',()=>$('#uc-close-dialog').showModal());$('#uc-confirm-close').addEventListener('click',()=>{$('#uc-close-dialog').close();void run(()=>action('close-match'));});
$('#uc-rules-open').addEventListener('click',()=>$('#uc-rules-dialog').showModal());
$('#uc-theme').addEventListener('click',()=>{const values=['system','light','dark'];window.ChuTheme.set(values[(values.indexOf(window.ChuTheme.get())+1)%3]);$('#uc-theme').textContent={system:'外观：跟随系统',light:'外观：浅色',dark:'外观：深色'}[window.ChuTheme.get()];});
for(const [selector,copy]of [['#uc-copy-code',()=>room.code],['#uc-copy-invite',()=>location.origin+'/undercover?room='+room.code]])$(selector).addEventListener('click',async()=>{try{await navigator.clipboard.writeText(copy());notice('已复制，可以发给朋友。');}catch{notice('请复制：'+copy());}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&room&&!busy)void run(async()=>{await sync();if(socket?.readyState!==WebSocket.OPEN)connect();});});
setInterval(renderClock,250);
async function init(){let saved;const requested=new URL(location.href).searchParams.get('room')?.toUpperCase();try{$('#uc-nickname').value=localStorage.getItem('chu-yiba:nickname')||'';saved=localStorage.getItem('chu-yiba:undercover-room');}catch{}if(requested)$('#uc-join-code').value=requested;if(saved&&(!requested||saved===requested)){try{accept(await api('/api/rooms/'+saved+'/state'));connect();}catch(error){if([403,404].includes(error.status)){try{localStorage.removeItem('chu-yiba:undercover-room');}catch{}}else{$('#uc-join-code').value=saved;notice('房间恢复暂时失败：'+error.message+' 原房间码已保留，可重新加入。','#uc-notice',true);}}}$('#uc-theme').textContent={system:'外观：跟随系统',light:'外观：浅色',dark:'外观：深色'}[window.ChuTheme.get()];}
void init();
